procedure:public.get_user_effective_perm.source_code:
DECLARE
    u_role text;
    perms TEXT[] := '{}';
BEGIN
    IF target_user_id IS NULL THEN
        RETURN perms;
    END IF;

    -- Check user role
    SELECT role::text INTO u_role FROM public.profiles WHERE id = target_user_id;

    IF u_role IS NULL THEN
        RETURN perms;
    END IF;

    -- If super_admin, return all available permission codes
    IF u_role = 'super_admin' THEN
        SELECT ARRAY_AGG(code) INTO perms FROM public.permissions;
        RETURN perms;
    END IF;

    -- Calculate effective permissions based on precedence:
    -- User Explicit DENY overrides ALL.
    -- Include User Explicit GRANT + Role Permissions, excluding Explicit DENY.
    SELECT ARRAY_AGG(DISTINCT code) INTO perms
    FROM (
        -- User Explicit Grants
        SELECT p.code
        FROM public.user_permissions up
        JOIN public.permissions p ON p.id = up.permission_id
        WHERE up.user_id = target_user_id AND up.effect = 'grant'

        UNION

        -- Role Baseline Permissions
        SELECT p.code
        FROM public.role_permissions rp
        JOIN public.roles r ON r.id = rp.role_id
        JOIN public.permissions p ON p.id = rp.permission_id
        WHERE r.name = u_role
    ) active_perms
    WHERE code NOT IN (
        -- User Explicit Denies
        SELECT p.code
        FROM public.user_permissions up
        JOIN public.permissions p ON p.id = up.permission_id
        WHERE up.user_id = target_user_id AND up.effect = 'deny'
    );

    RETURN COALESCE(perms, '{}');
END;

procedure:public.get_user_unread_convers.source_code:
DECLARE
    curr_user UUID := auth.uid();
    tot INT := 0;
BEGIN
    IF curr_user IS NULL THEN RETURN 0; END IF;

    SELECT COUNT(DISTINCT m.conversation_id)::int INTO tot
    FROM public.messages m
    JOIN public.conversation_members cm ON cm.conversation_id = m.conversation_id AND cm.user_id = curr_user AND cm.left_at IS NULL
    WHERE m.sender_id != curr_user
      AND m.deleted_at IS NULL
      AND (cm.last_read_at IS NULL OR m.sent_at > cm.last_read_at);

    RETURN tot;
END;

