procedure:public.update_lesson_progress(.source_code:
DECLARE
    s_id UUID;
    bounded_progress INT;
    is_completed BOOLEAN;
BEGIN
    SELECT id INTO s_id FROM public.students WHERE profile_id = auth.uid();
    IF s_id IS NULL THEN
        RAISE EXCEPTION 'Only active enrolled students can update lesson progress' USING ERRCODE = '42501';
    END IF;

    IF NOT public.current_student_can_access_lesson(p_lesson_id) THEN
        RAISE EXCEPTION 'Unauthorized to access this lesson' USING ERRCODE = '42501';
    END IF;

    bounded_progress := GREATEST(0, LEAST(100, p_progress_percentage));
    is_completed := (p_status = 'completed' OR bounded_progress >= 100);

    INSERT INTO public.lesson_progress (
        student_id,
        lesson_id,
        status,
        progress_percentage,
        last_position,
        time_spent_seconds,
        completed_at,
        last_accessed_at
    )
    VALUES (
        s_id,
        p_lesson_id,
        CASE WHEN is_completed THEN 'completed' ELSE p_status END,
        bounded_progress,
        p_last_position_seconds::text,
        p_time_spent_seconds,
        CASE WHEN is_completed THEN NOW() ELSE NULL END,
        NOW()
    )
    ON CONFLICT (student_id, lesson_id) DO UPDATE SET
        status = CASE WHEN EXCLUDED.status = 'completed' OR lesson_progress.status = 'completed' THEN 'completed' ELSE EXCLUDED.status END,
        progress_percentage = GREATEST(lesson_progress.progress_percentage, EXCLUDED.progress_percentage),
        last_position = EXCLUDED.last_position,
        time_spent_seconds = lesson_progress.time_spent_seconds + EXCLUDED.time_spent_seconds,
        completed_at = COALESCE(lesson_progress.completed_at, CASE WHEN EXCLUDED.status = 'completed' THEN NOW() ELSE NULL END),
        last_accessed_at = NOW();

    RETURN jsonb_build_object(
        'success', true,
        'student_id', s_id,
        'lesson_id', p_lesson_id,
        'progress_percentage', bounded_progress,
        'completed', is_completed
    );
END;

procedure:public.validate_and_create_sch.source_code:
DECLARE
    t_id UUID;
    new_sched_id UUID;
BEGIN
    -- Verify time order boundary
    IF p_end_time <= p_start_time THEN
        RAISE EXCEPTION 'Schedule end_time must be strictly after start_time' USING ERRCODE = '23514';
    END IF;

    -- Check Group Schedule Overlap
    IF EXISTS (
        SELECT 1 FROM public.schedules
        WHERE group_id = p_group_id
          AND day_of_week = p_day_of_week
          AND status = 'active'
          AND (p_start_time, p_end_time) OVERLAPS (start_time, end_time)
    ) THEN
        RAISE EXCEPTION 'Group has an overlapping active schedule slot on this day' USING ERRCODE = '23505';
    END IF;

    -- Resolve primary active teacher assigned to group
    SELECT teacher_id INTO t_id
    FROM public.group_teachers
    WHERE group_id = p_group_id AND is_primary = true AND effective_from <= CURRENT_DATE AND (effective_to IS NULL OR effective_to >= CURRENT_DATE)
    LIMIT 1;

    -- Check Teacher Schedule Overlap
    IF t_id IS NOT NULL THEN
        IF EXISTS (
            SELECT 1 FROM public.schedules s
            JOIN public.group_teachers gt ON gt.group_id = s.group_id
            WHERE gt.teacher_id = t_id
              AND s.day_of_week = p_day_of_week
              AND s.status = 'active'
              AND (p_start_time, p_end_time) OVERLAPS (s.start_time, s.end_time)
        ) THEN
            RAISE EXCEPTION 'Assigned primary teacher is scheduled in another group during this time slot' USING ERRCODE = '23505';
        END IF;
    END IF;

    -- Check Room Location Overlap (if location specified)
    IF p_room_location IS NOT NULL AND TRIM(p_room_location) != '' THEN
        IF EXISTS (
            SELECT 1 FROM public.schedules
            WHERE location = p_room_location
              AND day_of_week = p_day_of_week
              AND status = 'active'
              AND (p_start_time, p_end_time) OVERLAPS (start_time, end_time)
        ) THEN
            RAISE EXCEPTION 'Room location "%" is already booked during this time slot', p_room_location USING ERRCODE = '23505';
        END IF;
    END IF;

    -- Create schedule entry
    new_sched_id := gen_random_uuid();
    INSERT INTO public.schedules (id, group_id, day_of_week, start_time, end_time, location, status)
    VALUES (new_sched_id, p_group_id, p_day_of_week, p_start_time, p_end_time, p_room_location, 'active');

    RETURN jsonb_build_object(
        'success', true,
        'schedule_id', new_sched_id,
        'group_id', p_group_id,
        'message', 'Schedule created successfully'
    );
END;

